def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core = core.split('+', 1)[0]
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is not None:
            idents = pre.split('.')
        else:
            idents = None
        return (major, minor, patch, idents)

    def cmp_ident(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            return (ai > bi) - (ai < bi)
        elif a_num and not b_num:
            return -1
        elif not a_num and b_num:
            return 1
        else:
            return (a > b) - (a < b)

    def compare(v1, v2):
        maj1, min1, pat1, pre1 = parse(v1)
        maj2, min2, pat2, pre2 = parse(v2)
        if maj1 != maj2:
            return -1 if maj1 < maj2 else 1
        if min1 != min2:
            return -1 if min1 < min2 else 1
        if pat1 != pat2:
            return -1 if pat1 < pat2 else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        for a, b in zip(pre1, pre2):
            c = cmp_ident(a, b)
            if c != 0:
                return c
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1
        return 0

    import functools
    return sorted(versions, key=functools.cmp_to_key(compare))

